<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$_SESSION['csrf']??=bin2hex(random_bytes(24));
require_once $root.'/app/Core/UnifiedSidebar.php';
function drE($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function drAllowed():bool{if(($_SESSION['user']['role']??'')==='admin')return true;$p=$_SESSION['user']['permissions']??[];return !empty($p['technical_projects']['view'])||!empty($p['technical_projects']['manage']);}
if(!drAllowed()){http_response_code(403);exit('No tenés permiso para acceder al parte diario.');}
$uid=(int)($_SESSION['user']['id']??0);$eventId=(int)($_GET['event_id']??$_POST['event_id']??0);if($eventId<=0){http_response_code(400);exit('Jornada inválida.');}
$isAdmin=(($_SESSION['user']['role']??'')==='admin');$manage=$isAdmin||!empty(($_SESSION['user']['permissions']??[])['technical_projects']['manage']);
$sql="SELECT e.*,p.id project_id,p.project_number,p.name project_name,c.business_name FROM technical_schedule_events e JOIN projects p ON p.id=e.project_id JOIN clients c ON c.id=p.client_id WHERE e.id=?";$s=$db->prepare($sql);$s->execute([$eventId]);$event=$s->fetch();if(!$event){http_response_code(404);exit('Jornada inexistente.');}
$assigned=$db->prepare('SELECT COUNT(*) FROM technical_schedule_users WHERE event_id=? AND user_id=?');$assigned->execute([$eventId,$uid]);if(!$manage&&!(int)$assigned->fetchColumn()){http_response_code(403);exit('Esta jornada no está asignada a tu usuario.');}
$reportUser=$uid;if($manage&&!empty($_GET['user_id']))$reportUser=(int)$_GET['user_id'];
$check=$db->prepare('SELECT COUNT(*) FROM technical_schedule_users WHERE event_id=? AND user_id=?');$check->execute([$eventId,$reportUser]);if(!(int)$check->fetchColumn()&&!$isAdmin){$reportUser=$uid;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??'')){http_response_code(419);exit('Solicitud vencida.');}
 $hours=(float)str_replace(',','.',(string)($_POST['hours_worked']??'0'));if($hours<0||$hours>24){http_response_code(422);exit('Las horas trabajadas deben estar entre 0 y 24.');}$text=trim((string)($_POST['report_text']??''));$trans=trim((string)($_POST['transcription']??''));$finalize=isset($_POST['finalize']);
 $db->beginTransaction();try{$q=$db->prepare('INSERT INTO technical_daily_reports(event_id,user_id,hours_worked,report_text,transcription,completed_at) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE hours_worked=VALUES(hours_worked),report_text=VALUES(report_text),transcription=VALUES(transcription),completed_at=VALUES(completed_at),updated_at=CURRENT_TIMESTAMP');$q->execute([$eventId,$reportUser,$hours,$text,$trans,$finalize?date('Y-m-d H:i:s'):null]);$rid=(int)$db->lastInsertId();if(!$rid){$r=$db->prepare('SELECT id FROM technical_daily_reports WHERE event_id=? AND user_id=?');$r->execute([$eventId,$reportUser]);$rid=(int)$r->fetchColumn();}
 if(!empty($_FILES['audio']['tmp_name'])&&is_uploaded_file($_FILES['audio']['tmp_name'])){$mime=(string)(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['audio']['tmp_name']);$allowed=['audio/webm'=>'webm','video/webm'=>'webm','audio/ogg'=>'ogg','audio/mpeg'=>'mp3','audio/mp4'=>'m4a','audio/x-m4a'=>'m4a','audio/wav'=>'wav'];if(!isset($allowed[$mime]))throw new RuntimeException('Formato de audio no permitido.');if((int)$_FILES['audio']['size']>25*1024*1024)throw new RuntimeException('El audio supera 25 MB.');$dir=$root.'/storage/uploads/technical_reports/'.date('Y/m');if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('No se pudo crear la carpeta de audios.');$name='parte-'.$rid.'-'.bin2hex(random_bytes(6)).'.'.$allowed[$mime];$full=$dir.'/'.$name;if(!move_uploaded_file($_FILES['audio']['tmp_name'],$full))throw new RuntimeException('No se pudo guardar el audio.');$rel='storage/uploads/technical_reports/'.date('Y/m').'/'.$name;$db->prepare('INSERT INTO technical_daily_report_audio(report_id,file_path,mime_type,original_name) VALUES(?,?,?,?)')->execute([$rid,$rel,$mime,$_FILES['audio']['name']??'grabacion']);}
 if($finalize){$db->prepare("UPDATE technical_schedule_events SET status='realizado' WHERE id=?")->execute([$eventId]);}$db->commit();$_SESSION['report_msg']=$finalize?'Jornada finalizada y parte diario guardado.':'Parte diario guardado.';header('Location:?a=daily_report&event_id='.$eventId);exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();http_response_code(500);exit('No se pudo guardar el parte: '.drE($e->getMessage()));}
}
$r=$db->prepare('SELECT * FROM technical_daily_reports WHERE event_id=? AND user_id=?');$r->execute([$eventId,$reportUser]);$report=$r->fetch()?:[];$audios=[];if(!empty($report['id'])){$q=$db->prepare('SELECT * FROM technical_daily_report_audio WHERE report_id=? ORDER BY id DESC');$q->execute([(int)$report['id']]);$audios=$q->fetchAll();}$msg=$_SESSION['report_msg']??null;unset($_SESSION['report_msg']);$from=$event['start_time']?substr($event['start_time'],0,5):'—';$to=$event['end_time']?substr($event['end_time'],0,5):'—';
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Parte diario · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:24px 4%;max-width:900px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:15px}.hero{background:#171b20;color:#fff}.muted{color:var(--muted)}label{display:block;font-weight:750;margin:14px 0 6px}input,textarea{width:100%;box-sizing:border-box;padding:12px;border:1px solid #cbd1d7;border-radius:10px;font:inherit}textarea{min-height:130px;resize:vertical}.btn{border:0;border-radius:10px;padding:12px 16px;background:var(--o);color:#fff;font-weight:800;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.light{background:#edf0f3;color:var(--ink)}.finish{background:#18794e}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.flash{background:#eaf8f1;border:1px solid #b9e2cd;padding:12px;border-radius:10px}.rec{padding:14px;border:1px solid var(--line);border-radius:12px;background:#f7f8f9}.rec.recording{border-color:#d9534f;background:#fff5f5}.audio-row{margin:10px 0}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#edf0f3;font-size:12px}@media(max-width:900px){.main{margin-left:0;padding:14px 12px 90px}.actions .btn{flex:1}}</style></head><body><?php erpSidebar('my_day');?><main class="main"><section class="card hero"><span class="badge"><?=drE(ucfirst($event['status']))?></span><h1>Parte diario</h1><b><?=drE($event['project_number'].' · '.$event['project_name'])?></b><div><?=drE($event['business_name'])?> · <?=drE(date('d/m/Y',strtotime($event['work_date'])))?> · <?=drE($from.' – '.$to)?></div></section><?php if($msg):?><div class="flash"><?=drE($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="card" id="reportForm"><input type="hidden" name="csrf" value="<?=drE($_SESSION['csrf'])?>"><input type="hidden" name="event_id" value="<?=$eventId?>"><label>Horas trabajadas</label><input type="number" name="hours_worked" min="0" max="24" step="0.25" value="<?=drE($report['hours_worked']??'')?>" placeholder="Ej.: 8" required><label>Parte diario / trabajo realizado</label><textarea name="report_text" placeholder="Contá qué se hizo, qué quedó pendiente, problemas encontrados, materiales necesarios, etc."><?=drE($report['report_text']??'')?></textarea><label>Audio del parte</label><div class="rec" id="recBox"><p class="muted">Podés grabar el parte directamente desde el celular o adjuntar un audio.</p><div class="actions"><button type="button" class="btn" id="recordBtn">● Grabar audio</button><button type="button" class="btn light" id="stopBtn" disabled>■ Detener</button></div><div id="preview"></div><input type="file" name="audio" id="audioFile" accept="audio/*" style="margin-top:12px"></div><label>Transcripción</label><textarea name="transcription" id="transcription" placeholder="La transcripción automática se incorporará en la siguiente integración. Mientras tanto podés escribir o corregir el texto acá."><?=drE($report['transcription']??'')?></textarea><?php if($audios):?><div style="margin-top:15px"><b>Audios guardados</b><?php foreach($audios as $au):?><div class="audio-row">🎙 <?=drE($au['original_name']?:basename($au['file_path']))?> <span class="muted"><?=drE(date('d/m/Y H:i',strtotime($au['created_at'])))?></span></div><?php endforeach;?></div><?php endif;?><div class="actions"><button class="btn light" type="submit">Guardar borrador</button><button class="btn finish" type="submit" name="finalize" value="1" onclick="return confirm('¿Finalizar la jornada y marcarla como realizada?')">✓ Finalizar jornada</button><a class="btn light" href="?a=my_day&date=<?=drE($event['work_date'])?>">Volver</a></div></form></main><script>let recorder,chunks=[],stream;const rb=document.getElementById('recordBtn'),sb=document.getElementById('stopBtn'),box=document.getElementById('recBox'),preview=document.getElementById('preview'),file=document.getElementById('audioFile');if(!navigator.mediaDevices||!window.MediaRecorder){rb.disabled=true;rb.textContent='Grabación no disponible';}rb.onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});const ext=(blob.type.includes('ogg')?'ogg':'webm');const f=new File([blob],'parte-diario-'+Date.now()+'.'+ext,{type:blob.type});const dt=new DataTransfer();dt.items.add(f);file.files=dt.files;preview.innerHTML='';const audio=document.createElement('audio');audio.controls=true;audio.src=URL.createObjectURL(blob);preview.appendChild(audio);stream.getTracks().forEach(t=>t.stop());box.classList.remove('recording');rb.disabled=false;sb.disabled=true;};recorder.start();box.classList.add('recording');rb.disabled=true;sb.disabled=false;rb.textContent='Grabando…';}catch(e){alert('No se pudo acceder al micrófono. Revisá el permiso del navegador.')}};sb.onclick=()=>{if(recorder&&recorder.state!=='inactive'){recorder.stop();rb.textContent='● Grabar audio'}};</script></body></html>